def mark_legacy_placeholders(apps, schema_editor):
    """One-off: the web form used to store the enterprise contact as the lone
    participant without any marker. Mark those (single participant carrying the
    contact's or company's name) so they are not mistaken for trainees."""
    Client = apps.get_model("enrollment", "Client")
    Participant = apps.get_model("enrollment", "Participant")
    Placeholder = apps.get_model("bridge", "ContactPlaceholder")
    for client in Client.objects.filter(client_type="enterprise"):
        people = list(Participant.objects.filter(client=client)[:2])
        names = {(client.responsible_name or "").strip(), (client.company_name or "").strip()} - {""}
        if len(people) == 1 and (people[0].full_name or "").strip() in names:
            Placeholder.objects.get_or_create(participant=people[0])


